// src/components/VotingPage.js
import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  const [showModal, setShowModal] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [modalType, setModalType] = useState("confirm");
  const [selectedCandidate, setSelectedCandidate] = useState(null);

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(res.data);
      } catch (error) {
        setModalMessage("Failed to load candidates.");
        setModalType("error");
        setShowModal(true);
      } finally {
        setLoading(false);
      }
    };
    fetchCandidates();
  }, []);

  const handleVote = (candidateId) => {
    if (submitting) return;
    setSelectedCandidate(candidateId);
    setModalType("confirm");
    setModalMessage(
      "Please confirm your vote. This action cannot be changed once submitted."
    );
    setShowModal(true);
  };

  const confirmVote = async () => {
    try {
      setSubmitting(true);

      await axios.post(
        `${API_URL}/api/vote/batch`,
        { candidateIds: [selectedCandidate] },
        {
          headers: {
            Authorization: `Bearer ${auth?.token}`,
          },
        }
      );

      setModalType("success");
      setModalMessage("Your vote has been recorded successfully.");
    } catch (error) {
      setModalType("error");
      setModalMessage("Voting failed or you may have already voted.");
    } finally {
      setSubmitting(false);
    }
  };

  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, candidate) => {
      const position = candidate.candidacy;
      if (!groups[position]) groups[position] = [];
      groups[position].push(candidate);
      return groups;
    }, {});
  }, [candidates]);

  if (loading) {
    return <div style={styles.center}>Loading candidates...</div>;
  }

  if (candidates.length === 0) {
    return <div style={styles.center}>No candidates available.</div>;
  }

  return (
    <div style={styles.page}>
      {/* HEADER */}
      <div style={styles.header}>
        <h1 style={styles.title}>Student Election 2026</h1>
        <p style={styles.subtitle}>
          Select your preferred candidate for each position
        </p>
      </div>

      {Object.entries(groupedCandidates).map(([position, list]) => (
        <div key={position} style={styles.section}>
          <div style={styles.positionHeader}>
            <div style={styles.positionLine}></div>
            <h2>{position}</h2>
          </div>

          <div style={styles.grid}>
            {list.map((candidate) => (
              <div key={candidate._id} style={styles.card}>
                {candidate.image && (
                  <img
                    src={`${API_URL}/uploads/${candidate.image}`}
                    alt={`${candidate.firstName} ${candidate.lastName}`}
                    style={styles.image}
                  />
                )}

                <h3 style={styles.name}>
                  {candidate.firstName} {candidate.lastName}
                </h3>

                <p style={styles.meta}>
                  {candidate.yearLevel} • {candidate.block}
                </p>

                <p style={styles.party}>
                  {candidate.partylist || "Independent"}
                </p>

                <button
                  onClick={() => handleVote(candidate._id)}
                  disabled={submitting}
                  style={styles.voteButton}
                >
                  {submitting ? "Submitting..." : "Cast Vote"}
                </button>
              </div>
            ))}
          </div>
        </div>
      ))}

      {/* MODAL */}
      {showModal && (
        <div style={styles.overlay}>
          <div style={styles.modal}>
            <h3 style={{ marginBottom: 15 }}>
              {modalType === "confirm"
                ? "Confirm Vote"
                : modalType === "success"
                ? "Success"
                : "Error"}
            </h3>

            <p style={{ marginBottom: 25 }}>{modalMessage}</p>

            {modalType === "confirm" ? (
              <div style={styles.modalButtons}>
                <button
                  style={styles.cancelBtn}
                  onClick={() => setShowModal(false)}
                >
                  Cancel
                </button>

                <button
                  style={styles.confirmBtn}
                  onClick={confirmVote}
                  disabled={submitting}
                >
                  {submitting ? "Processing..." : "Confirm"}
                </button>
              </div>
            ) : (
              <button
                style={styles.confirmBtn}
                onClick={() => setShowModal(false)}
              >
                Close
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

/* ================= STYLES ================= */

const styles = {
  page: {
    padding: "60px 30px",
    maxWidth: 1300,
    margin: "auto",
    fontFamily: "'Inter', sans-serif",
    background: "linear-gradient(to bottom, #eef2ff, #f8fafc)",
    minHeight: "100vh",
  },
  header: {
    textAlign: "center",
    marginBottom: 70,
  },
  title: {
    fontSize: 40,
    fontWeight: 700,
    color: "#111827",
  },
  subtitle: {
    marginTop: 12,
    color: "#6b7280",
    fontSize: 16,
  },
  section: {
    marginBottom: 70,
  },
  positionHeader: {
    display: "flex",
    alignItems: "center",
    gap: 15,
    marginBottom: 30,
  },
  positionLine: {
    width: 6,
    height: 30,
    background: "#4f46e5",
    borderRadius: 5,
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
    gap: 30,
  },
  card: {
    background: "#ffffff",
    borderRadius: 20,
    padding: 25,
    textAlign: "center",
    boxShadow: "0 15px 35px rgba(0,0,0,0.06)",
    transition: "0.3s ease",
  },
  image: {
    width: "100%",
    height: 220,
    objectFit: "cover",
    borderRadius: 15,
    marginBottom: 18,
  },
  name: {
    fontSize: 20,
    fontWeight: 600,
  },
  meta: {
    fontSize: 14,
    color: "#6b7280",
    marginTop: 5,
  },
  party: {
    fontSize: 14,
    marginTop: 10,
    marginBottom: 18,
    fontWeight: 500,
    color: "#374151",
  },
  voteButton: {
    width: "100%",
    padding: 14,
    borderRadius: 12,
    border: "none",
    background: "linear-gradient(135deg, #6366f1, #4338ca)",
    color: "#fff",
    fontWeight: 600,
    fontSize: 15,
    cursor: "pointer",
    transition: "0.2s",
  },
  center: {
    padding: 50,
    textAlign: "center",
    fontSize: 18,
  },
  overlay: {
    position: "fixed",
    inset: 0,
    backgroundColor: "rgba(0,0,0,0.55)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },
  modal: {
    background: "#fff",
    padding: 35,
    borderRadius: 18,
    width: 420,
    textAlign: "center",
    boxShadow: "0 25px 60px rgba(0,0,0,0.25)",
  },
  modalButtons: {
    display: "flex",
    justifyContent: "space-between",
  },
  cancelBtn: {
    padding: "12px 20px",
    borderRadius: 10,
    border: "none",
    backgroundColor: "#e5e7eb",
    cursor: "pointer",
  },
  confirmBtn: {
    padding: "12px 20px",
    borderRadius: 10,
    border: "none",
    backgroundColor: "#4f46e5",
    color: "#fff",
    cursor: "pointer",
  },
};

export default VotingPage;
